def bowling_score(rolls):
    if not all(isinstance(r, int) and 0 <= r <= 10 for r in rolls):
        raise ValueError("Invalid roll value")

    score = 0
    idx = 0
    for frame in range(10):
        if idx >= len(rolls):
            raise ValueError("Too few rolls")
        if rolls[idx] == 10:
            if idx + 2 >= len(rolls):
                raise ValueError("Too few rolls")
            score += 10 + rolls[idx+1] + rolls[idx+2]
            idx += 1
        else:
            if idx + 1 >= len(rolls):
                raise ValueError("Too few rolls")
            two = rolls[idx] + rolls[idx+1]
            if two > 10:
                raise ValueError("Frame total exceeds 10")
            if two == 10:
                if idx + 2 >= len(rolls):
                    raise ValueError("Too few rolls")
                score += 10 + rolls[idx+2]
            else:
                score += two
            idx += 2

    if idx != len(rolls):
        raise ValueError("Too many rolls")

    return score
